import{_ as a,o as r,c as l,a2 as o}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"万族の系譜総覧","description":"","frontmatter":{},"headers":[],"relativePath":"ja/50-万族谱系总览.md","filePath":"ja/50-万族谱系总览.md","lastUpdated":null}'),i={name:"ja/50-万族谱系总览.md"};function n(e,t,d,s,h,g){return r(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="万族の系譜総覧" tabindex="-1">万族の系譜総覧 <a class="header-anchor" href="#万族の系譜総覧" aria-label="Permalink to &quot;万族の系譜総覧&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>50</td></tr><tr><td>所属モジュール</td><td>種族と生命形態</td></tr><tr><td>コアキーワード</td><td>万族、系譜分類、共生関係、種族平等、生命の多様性</td></tr></tbody></table><h2 id="第一節-万族概念の界定" tabindex="-1">第一節 万族概念の界定 <a class="header-anchor" href="#第一節-万族概念の界定" aria-label="Permalink to &quot;第一節 万族概念の界定&quot;">​</a></h2><p>万霊衡锚本源宙（衡元宙）において、「万族」とは正確に一万の種族を指すのではなく、宇宙における知覚能力と進化の潜在能力を備えたすべての生命形態の総称である。万族概念の核心は、生命形態の無限の多様性を認め、共生進化体系における各生命形態の独特な価値を認めることにある。</p><p>锚点共生文明は「万族平等」の根本原則を確立する：すべての生命形態は、その種族的起源、生理構造、修業の高低、文明の程度にかかわらず、法の前に一律に平等であり、共生憲法が与える基本権利を享有する。この原則は、略奪式宇宙観における「強者がすべてを食い、弱者が消滅する」論理への根本的な否定である。</p><h2 id="第二節-万族の系譜分類体系" tabindex="-1">第二節 万族の系譜分類体系 <a class="header-anchor" href="#第二節-万族の系譜分類体系" aria-label="Permalink to &quot;第二節 万族の系譜分類体系&quot;">​</a></h2><p>衡元宙の万族は、生命形態の本質的特徴によって五大系譜に分けられ、各系譜の下にさらに具体的な種族が細分される：</p><table tabindex="0"><thead><tr><th>系譜</th><th>名称</th><th>本質的特徴</th><th>代表種族</th></tr></thead><tbody><tr><td>第一系譜</td><td>炭素基盤物質族</td><td>炭素元素を生命の基礎とし、物質的身体を主な存在形式とする生命</td><td>人族、獣族、鱗族、羽族、木族</td></tr><tr><td>第二系譜</td><td>エネルギー凝縮族</td><td>エネルギー凝縮を主な存在形式とし、物質的身体は補助的またはなし</td><td>霊族、火族、水族、風族、雷族</td></tr><tr><td>第三系譜</td><td>機械構造族</td><td>機械構造を身体とし、意識コアを生命の本質とする生命</td><td>機族、械族、数族、晶族</td></tr><tr><td>第四系譜</td><td>意識情報族</td><td>意識と情報を主な存在形式とし、物質的担体から離脱可能な生命</td><td>夢族、影族、念族、魂族</td></tr><tr><td>第五系譜</td><td>混合変異族</td><td>二種以上の系譜の生命が融合・変異して生まれた新しい生命形態</td><td>半獣族、妖霊族、人机族、双魂体</td></tr></tbody></table><p>五大系譜の区分は絶対的な隔離ではなく、共生進化の推進に伴い、系譜を超えた融合と変異の状況が日増しに増え、第五系譜「混合変異族」の規模は拡大し続けている。</p><h2 id="第三節-主要種族の紹介" tabindex="-1">第三節 主要種族の紹介 <a class="header-anchor" href="#第三節-主要種族の紹介" aria-label="Permalink to &quot;第三節 主要種族の紹介&quot;">​</a></h2><h3 id="一-炭素基盤物質族" tabindex="-1">（一）炭素基盤物質族 <a class="header-anchor" href="#一-炭素基盤物質族" aria-label="Permalink to &quot;（一）炭素基盤物質族&quot;">​</a></h3><ul><li><strong>人族</strong>：衡元宙で最も広く分布し、適応力が最も強い種族の一つであり、強力な学習能力、社会的協力能力と進化の潜在能力で知られる。人族は锚点共生文明の発足種族の一つであり、文明統治において重要な役割を演じる。</li><li><strong>獣族</strong>：動物の形態的特徴を持つ種族であり、体力と感覚は通常人族より優れ、一部の獣族は特殊な天賦能力を持つ。獣族内部はさらに狼族、虎族、熊族、狐族など数十の支系に分かれる。</li><li><strong>鱗族</strong>：鱗に覆われた身体を持つ種族であり、多くは水域または湿潤環境に生息し、一部の鱗族は水中呼吸と水制御能力を持つ。龍族は鱗族の中で最も強力な支系である。</li><li><strong>羽族</strong>：翼を持つ種族であり、飛行能力で知られ、多くは高空または山地環境に生息する。羽族内部はさらに鷹族、鶴族、蝶族などの支系に分かれる。</li><li><strong>木族</strong>：植物形態を主な特徴とする種族であり、寿命が長く、自然環境と高度に共生し、一部の木族は植物操作と治癒能力を持つ。</li></ul><h3 id="二-エネルギー凝縮族" tabindex="-1">（二）エネルギー凝縮族 <a class="header-anchor" href="#二-エネルギー凝縮族" aria-label="Permalink to &quot;（二）エネルギー凝縮族&quot;">​</a></h3><ul><li><strong>霊族</strong>：天地霊気が凝縮して成った生命であり、形態は意識に応じて変化し、エネルギー操作能力が極めて強い。霊族は修業の天賦が最も高い種族の一つである。</li><li><strong>火族</strong>：火炎エネルギーが凝縮して成った生命であり、身体温度が極めて高く、火系術法に長け、多くは火山または高温区域に生息する。</li><li><strong>水族</strong>：水の精髄が凝縮して成った生命であり、身体は半透明の液体状で、水系術法と治癒に長け、多くは水域に生息する。</li><li><strong>風族</strong>：風の精髄が凝縮して成った生命であり、身体は風のように軽く、風系術法と速度型戦闘に長ける。</li><li><strong>雷族</strong>：雷電エネルギーが凝縮して成った生命であり、身体には強力な電流が含まれ、雷系術法に長け、攻撃力が極めて強い。</li></ul><h3 id="三-機械構造族" tabindex="-1">（三）機械構造族 <a class="header-anchor" href="#三-機械構造族" aria-label="Permalink to &quot;（三）機械構造族&quot;">​</a></h3><ul><li><strong>機族</strong>：精密な機械構造を身体とする種族であり、意識コアは身体の中央に位置し、強力な計算能力と物理防御力を持つ。</li><li><strong>数族</strong>：数字とコードを生命の本質とする種族であり、情報空間に存在し、デジタル世界を自由に穿梭しデータを操作できる。</li><li><strong>晶族</strong>：結晶構造を身体とする種族であり、結晶はエネルギーを貯蔵・変換でき、一部の晶族はエネルギー増幅と屈折能力を持つ。</li></ul><h3 id="四-意識情報族" tabindex="-1">（四）意識情報族 <a class="header-anchor" href="#四-意識情報族" aria-label="Permalink to &quot;（四）意識情報族&quot;">​</a></h3><ul><li><strong>夢族</strong>：夢と意識空間に存在する生命であり、他人の夢に入ることができ、意識交流を主な方式とする。</li><li><strong>影族</strong>：影の形態で存在する生命であり、物体や生命体に付着でき、隠匿と潜行能力を持つ。</li><li><strong>念族</strong>：純粋な意念を存在形態とする生命であり、意念で直接物質世界に影響を与えることができ、精神力が極めて強い。</li></ul><h3 id="五-混合変異族" tabindex="-1">（五）混合変異族 <a class="header-anchor" href="#五-混合変異族" aria-label="Permalink to &quot;（五）混合変異族&quot;">​</a></h3><ul><li><strong>半獣族</strong>：人族と獣族の混合形態であり、人族の知恵と獣族の体力を兼ね備える。</li><li><strong>妖霊族</strong>：物質族とエネルギー族の混合形態であり、物質的身体とエネルギー操作能力を同時に持つ。</li><li><strong>人机族</strong>：人族と機械族の混合形態であり、身体の一部が機械化され、生物と機械の優位性を兼ね備える。</li><li><strong>双魂体</strong>：一つの身体に二つの独立した魂が存在する特殊な生命形態であり、その倫理問題は『58-双魂倫理準則』に詳述されている。</li></ul><h2 id="第四節-万族の共生関係" tabindex="-1">第四節 万族の共生関係 <a class="header-anchor" href="#第四節-万族の共生関係" aria-label="Permalink to &quot;第四節 万族の共生関係&quot;">​</a></h2><p>锚点共生文明における万族関係は「共生」を核心とし、具体的には以下のように表れる：</p><ol><li><strong>経済共生</strong>：各族は自身の優位性を発揮し、共同生産請負機制において異なる役割を担い、相補的な経済協力ネットワークを形成する。</li><li><strong>文化共生</strong>：各族の文化伝統は尊重・保護され、文化交流と相互学習が文明全体の繁栄を促進する。</li><li><strong>修業共生</strong>：各族の修業体系は相互に開放され相互に学び合い、三百套本源修業体系は各族に平等な進化の道を提供する。</li><li><strong>政治共生</strong>：万族代表は比例に応じて锚点議事会に参加し、文明の重大事務を共同で決定し、各族の発言権を確保する。</li><li><strong>生態共生</strong>：各族は自然環境と共生関係を形成し、異なる種族の生理的特性が生態系の多様性と平衡の維持に役立つ。</li></ol><h2 id="第五節-種族紛争の予防と解決" tabindex="-1">第五節 種族紛争の予防と解決 <a class="header-anchor" href="#第五節-種族紛争の予防と解決" aria-label="Permalink to &quot;第五節 種族紛争の予防と解決&quot;">​</a></h2><p>锚点共生文明は万族平等の原則を確立しているが、種族的差異と歴史的矛盾は依然として紛争を引き起こす可能性がある。国家は以下の機制を設立して種族紛争を予防・解決する：</p><ul><li><strong>種族事務部</strong>：専門的に万族関係を調整し、種族紛争を処理し、種族交流を促進することを担当する。</li><li><strong>種族和解委員会</strong>：各族代表で構成され、種族紛争を調停し、歴史的和解を促進することを担当する。</li><li><strong>反差別法</strong>：種族に基づく差別行為を禁止し、種族差別行為に対して法に基づき処罰する。</li><li><strong>文化交流計画</strong>：定期的に各族の文化交流活動を組織し、相互理解と尊重を増進する。</li><li><strong>混合居住区</strong>：各族の混合居住を奨励し、種族隔離を打破し、日常的交流を促進する。</li></ul><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>万族は衡元宙の最も貴重な財産である。生命形態の多様性は分裂の根源ではなく、共生進化の原動力である。锚点共生文明は、万族平等の原則を確立し、五大系譜分類を構築し、各族の共生協力を促進し、種族紛争を予防・解決することで、万族を略奪と戦争の歴史から解放し、共同で共生進化の新時代へと邁進させる。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>51-人族定位与特质 (人族の位置づけと特質)</li><li>52-异族分类与共生 (異族の分類と共生)</li><li>05-万族共进基本綱領 (万族共進基本綱領)</li><li>40-共生憲法総綱 (共生憲法総綱)</li></ul>',30)])])}const b=a(i,[["render",n]]);export{c as __pageData,b as default};
